class Solution {
public:
    int diameterOfBinaryTree(TreeNode* root) {
        if (root == nullptr) return 0;

        struct Frame {
            TreeNode* node;
            int state;
            int leftHeight;
            int rightHeight;
        };

        vector<Frame> st;
        st.push_back({root, 0, -1, -1});

        int answer = 0;

        while (!st.empty()) {
            Frame &frame = st.back();
            TreeNode* node = frame.node;

            if (frame.state == 0) {
                frame.state = 1;
                if (node->left != nullptr) {
                    st.push_back({node->left, 0, -1, -1});
                }
            } else if (frame.state == 1) {
                frame.state = 2;
                if (node->right != nullptr) {
                    st.push_back({node->right, 0, -1, -1});
                }
            } else {
                int leftHeight = frame.leftHeight;
                int rightHeight = frame.rightHeight;
                answer = max(answer, leftHeight + rightHeight + 2);
                int nodeHeight = 1 + max(leftHeight, rightHeight);

                st.pop_back();

                if (!st.empty()) {
                    if (st.back().state == 1) {
                        st.back().leftHeight = nodeHeight;
                    } else {
                        st.back().rightHeight = nodeHeight;
                    }
                }
            }
        }

        return answer;
    }
};

