class Solution {
    static class Frame {
        TreeNode node;
        int state;
        int leftHeight;
        int rightHeight;

        Frame(TreeNode node, int state, int leftHeight, int rightHeight) {
            this.node = node;
            this.state = state;
            this.leftHeight = leftHeight;
            this.rightHeight = rightHeight;
        }
    }

    public int diameterOfBinaryTree(TreeNode root) {
        if (root == null) return 0;

        ArrayDeque<Frame> stack = new ArrayDeque<>();
        stack.push(new Frame(root, 0, -1, -1));
        int answer = 0;

        while (!stack.isEmpty()) {
            Frame frame = stack.peek();

            if (frame.state == 0) {
                frame.state = 1;
                if (frame.node.left != null) {
                    stack.push(new Frame(frame.node.left, 0, -1, -1));
                }
            } else if (frame.state == 1) {
                frame.state = 2;
                if (frame.node.right != null) {
                    stack.push(new Frame(frame.node.right, 0, -1, -1));
                }
            } else {
                answer = Math.max(answer, frame.leftHeight + frame.rightHeight + 2);
                int nodeHeight = 1 + Math.max(frame.leftHeight, frame.rightHeight);
                stack.pop();

                if (!stack.isEmpty()) {
                    Frame parent = stack.peek();
                    if (parent.state == 1) {
                        parent.leftHeight = nodeHeight;
                    } else {
                        parent.rightHeight = nodeHeight;
                    }
                }
            }
        }

        return answer;
    }
}

