    const root = new TreeNode(values[0]);
    const queue = [root];
    let head = 0;
    let i = 1;

    while (head < queue.length && i < values.length) {
        const node = queue[head++];

        if (values[i] !== null) {
            node.left = new TreeNode(values[i]);
            queue.push(node.left);
        }
        i++;

        if (i < values.length && values[i] !== null) {
            node.right = new TreeNode(values[i]);
            queue.push(node.right);
        }
        i++;
    }

    return root;
}

function diameterOfBinaryTree(root) {
    if (root === null) return 0;

    // Each frame is [node, state, leftHeight, rightHeight].
    // state 0 = enter, 1 = left done, 2 = right done.
    const stack = [[root, 0, -1, -1]];
    let answer = 0;

    while (stack.length > 0) {
        const frame = stack[stack.length - 1];
        const node = frame[0];

        if (frame[1] === 0) {
            frame[1] = 1;
            if (node.left !== null) {
                stack.push([node.left, 0, -1, -1]);
            }
        } else if (frame[1] === 1) {
            frame[1] = 2;
            if (node.right !== null) {
                stack.push([node.right, 0, -1, -1]);
            }
        } else {
            answer = Math.max(answer, frame[2] + frame[3] + 2);
            const nodeHeight = 1 + Math.max(frame[2], frame[3]);
            stack.pop();

            if (stack.length > 0) {
                const parent = stack[stack.length - 1];
                if (parent[1] === 1) {
                    parent[2] = nodeHeight;
                } else {
                    parent[3] = nodeHeight;
                }
            }
        }
    }

    return answer;
}

