static struct TreeNode *new_node(int value) {
    struct TreeNode *node = (struct TreeNode *)malloc(sizeof(struct TreeNode));
    if (!node) exit(EXIT_FAILURE);
    node->val = value;
    node->left = NULL;
    node->right = NULL;
    return node;
