static void skip_separators(void) {
    while (*ptr &&
           (isspace((unsigned char)*ptr) || *ptr == ',')) {
        ++ptr;
    }
}

static int next_value(int *is_null, int *value) {
    skip_separators();

    if (*ptr == '\0' || *ptr == ']') return 0;

    if (strncmp(ptr, "null", 4) == 0) {
        ptr += 4;
        *is_null = 1;
        return 1;
    }

    char *end = NULL;
    long parsed = strtol(ptr, &end, 10);
    if (end == ptr) return 0;

    ptr = end;
    *is_null = 0;
    *value = (int)parsed;
    return 1;
}

static struct TreeNode *parse_tree(const char *input) {
    const char *first = strchr(input, '[');
    if (!first) return NULL;

    ptr = strchr(first + 1, '[');
    if (!ptr) return NULL;
    ++ptr;

    int is_null = 0;
    int value = 0;

    if (!next_value(&is_null, &value) || is_null) return NULL;

    struct TreeNode *root = new_node(value);

    size_t capacity = 16;
    size_t head = 0;
    size_t tail = 0;
    struct TreeNode **queue =
        (struct TreeNode **)malloc(capacity * sizeof(*queue));
    if (!queue) exit(EXIT_FAILURE);

    queue[tail++] = root;

    while (head < tail) {
        struct TreeNode *node = queue[head++];

        if (!next_value(&is_null, &value)) break;
        if (!is_null) {
            node->left = new_node(value);
            if (tail == capacity) {
                capacity *= 2;
                queue = (struct TreeNode **)realloc(
                    queue, capacity * sizeof(*queue));
                if (!queue) exit(EXIT_FAILURE);
            }
            queue[tail++] = node->left;
        }

        if (!next_value(&is_null, &value)) break;
        if (!is_null) {
            node->right = new_node(value);
            if (tail == capacity) {
                capacity *= 2;
                queue = (struct TreeNode **)realloc(
                    queue, capacity * sizeof(*queue));
                if (!queue) exit(EXIT_FAILURE);
            }
            queue[tail++] = node->right;
        }
    }

    free(queue);
    return root;
}

static int diameter_of_binary_tree(struct TreeNode *root) {
    if (!root) return 0;

    size_t capacity = 32;
    size_t top = 0;
    struct Frame *stack =
        (struct Frame *)malloc(capacity * sizeof(*stack));
    if (!stack) exit(EXIT_FAILURE);

    int answer = 0;

    stack[top++] = (struct Frame){root, 0, -1, -1};

    while (top > 0) {
        struct Frame *frame = &stack[top - 1];
        struct TreeNode *node = frame->node;

        if (frame->state == 0) {
            frame->state = 1;

            if (node->left) {
                if (top == capacity) {
                    capacity *= 2;
                    stack = (struct Frame *)realloc(
                        stack, capacity * sizeof(*stack));
                    if (!stack) exit(EXIT_FAILURE);
                }
                stack[top++] = (struct Frame){node->left, 0, -1, -1};
            }
        } else if (frame->state == 1) {
            frame->state = 2;

            if (node->right) {
                if (top == capacity) {
                    capacity *= 2;
                    stack = (struct Frame *)realloc(
                        stack, capacity * sizeof(*stack));
                    if (!stack) exit(EXIT_FAILURE);
                }
                stack[top++] = (struct Frame){node->right, 0, -1, -1};
            }
        } else {
            int left_height = frame->left_height;
            int right_height = frame->right_height;
            int through = left_height + right_height + 2;
            int node_height =
                1 + (left_height > right_height ? left_height : right_height);

            if (through > answer) answer = through;

            --top;
            if (top > 0) {
                struct Frame *parent = &stack[top - 1];
                if (parent->state == 1) {
                    parent->left_height = node_height;
                } else {
                    parent->right_height = node_height;
                }
            }
        }
    }

    free(stack);
    return answer;
}

static void free_tree(struct TreeNode *root) {
    if (!root) return;

    size_t capacity = 16;
    size_t top = 0;
    struct TreeNode **stack =
        (struct TreeNode **)malloc(capacity * sizeof(*stack));
    if (!stack) exit(EXIT_FAILURE);

    stack[top++] = root;

    while (top > 0) {
        struct TreeNode *node = stack[--top];

        if (node->left) {
            if (top == capacity) {
                capacity *= 2;
                stack = (struct TreeNode **)realloc(
                    stack, capacity * sizeof(*stack));
                if (!stack) exit(EXIT_FAILURE);
